def get_neighbors(grid, r, c):
    neighs = set()
    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            neighs.add(grid[nr][nc])
    return neighs

